    topic: $("#quiz-topic")?.value || "all",
    session: $("#quiz-session")?.value === "teorico" ? "teorico" : "libre",
    mode: $("#quiz-mode")?.value || "study",
    pretest: !!$("#quiz-pretest")?.checked,
    wrongOnly: !!$("#quiz-wrong-only")?.checked,
    trapOnly: !!$("#quiz-trap-only")?.checked
